package com.agriconnect.order;import io.micrometer.core.instrument.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Component;@Component class OperationalMetrics{private final JdbcClient db;OperationalMetrics(JdbcClient d,MeterRegistry registry){db=d;Gauge.builder("agriconnect.outbox.unpublished",this,x->x.count("select count(*) from outbox_events where status='PENDING'")).tag("service","order-service").register(registry);Gauge.builder("agriconnect.orders.total",this,x->x.count("select count(*) from orders")).tag("service","order-service").register(registry);Gauge.builder("agriconnect.orders.failed_compensation",this,x->x.count("select count(*) from order_sagas where state='COMPENSATION_FAILED'")).tag("service","order-service").register(registry);}double count(String sql){try{return db.sql(sql).query(Long.class).single();}catch(Exception e){return Double.NaN;}}}
